#pragma once#include "BaseReader.h"class KRTMR : public KBaseReader{public:  KRTMR();  virtual std::string GetType() const  {    return "RTMR";  }  virtual void GetSettings( tVectoredString_ &set, tParamsCont_ &params )  {    __super::GetSettings( set, params );    set = m_settings;  }protected:  virtual BOOL OnParsingSingleText( std::string &szText, RECTL *rc );private:  int m_CurParameterID;  int m_ReadParams;  tVectoredString_ m_settings;};//////////////////////////////////////////////////////////////////////////class KRTMRFactory : public TIntrusivePtrImpl<IParamReaderFactory>{public:  virtual IParameterReadPtr CreateReader()  {    IParameterReadPtr ptr;    ptr = new KRTMR();    return ptr;  }};